        var cachedValue = _memoryCache.GetOrCreate(
            CacheKeys.Entry,
            cacheEntry =>
            {
                cacheEntry.AbsoluteExpirationRelativeToNow = TimeSpan.FromSeconds(20);
                return DateTime.Now;
            });
        // </snippet_OnGetCacheGetOrCreateAbsolute>
